{
  "title": "The Gilded Cage",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined city gates.",
      "visual_description": "Crumbling stone gates flanked by broken statues, overgrown with thorny vines under a pale grey sky.",
      "characters": ["Elara", "Dorn", "Lys"]
    },
    {
      "scene_number": 2,
      "caption": "They encounter frightened townspeople in a square.",
      "visual_description": "A cobblestone square with a dry fountain, huddled families clutching meager belongings, eyes wide with fear.",
      "characters": ["Elara", "Dorn", "Lys", "Mira", "Old Torvin"]
    },
    {
      "scene_number": 3,
      "caption": "An armored patrol blocks the main road.",
      "visual_description": "Four soldiers in rusted but ornate armor, bearing faded royal crests, standing at attention before a barricade.",
      "characters": ["Elara", "Dorn", "Lys", "Sergeant Vex", "Guard 1", "Guard 2", "Guard 3", "Guard 4"]
    },
    {
      "scene_number": 4,
      "caption": "The party slips past through a side alley.",
      "visual_description": "Narrow, shadowed alley with dripping gutters and a stray cat hissing from a windowsill.",
      "characters": ["Elara", "Dorn", "Lys"]
    },
    {
      "scene_number": 5,
      "caption": "They find an old royal banner torn and trampled.",
      "visual_description": "A mud-soaked banner with a golden lion on crimson, half-buried in the street beside a collapsed cart.",
      "characters": ["Elara", "Dorn", "Lys"]
    },
    {
      "scene_number": 6,
      "caption": "A magic door appears in a forgotten wall.",
      "visual_description": "A stone wall flickers, revealing an ornate door carved with glowing runes, pulsing with a soft blue light.",
      "characters": ["Elara", "Dorn", "Lys"]
    },
    {
      "scene_number": 7,
      "caption": "Inside, they face a cursed tower's illusion.",
      "visual_description": "A spiral staircase that seems to loop back on itself, walls covered in shifting, mocking faces made of shadow.",
      "characters": ["Elara", "Dorn", "Lys"]
    },
    {
      "scene_number": 8,
      "caption": "A rumor of dragons echoes through the halls.",
      "visual_description": "A vast, empty hall with scorch marks on the floor and ceiling, and a distant roar shaking the dust from the rafters.",
      "characters": ["Elara", "Dorn", "Lys"]
    },
    {
      "scene_number": 9,
      "caption": "They find the captive in a throne room.",
      "visual_description": "A broken throne at the far end of a cavernous room, chains of light binding a figure in tattered robes.",
      "characters": ["Elara", "Dorn", "Lys", "Kaelen"]
    },
    {
      "scene_number": 10,
      "caption": "The magic door seals behind them.",
      "visual_description": "The door melts into solid stone, runes fading to dull grey, leaving no trace of an exit.",
      "characters": ["Elara", "Dorn", "Lys", "Kaelen"]
    },
    {
      "scene_number": 11,
      "caption": "A phantom dragon swoops through the hall.",
      "visual_description": "A translucent, ghostly dragon with glowing blue eyes dives through the ceiling, passing through pillars without breaking them.",
      "characters": ["Elara", "Dorn", "Lys", "Kaelen", "Phantom Dragon"]
    },
    {
      "scene_number": 12,
      "caption": "An armored patrol ambushes them from a side corridor.",
      "visual_description": "Soldiers burst from a hidden door, shields locked, spears leveled, forming a tight phalanx.",
      "characters": ["Elara", "Dorn", "Lys", "Kaelen", "Sergeant Vex", "Guard 1", "Guard 2", "Guard 3", "Guard 4"]
    },
    {
      "scene_number": 13,
      "caption": "Dorn holds the rearguard while the others flee.",
      "visual_description": "Dorn stands with his back to a doorway, shield raised, bracing against a rain of sword blows from the patrol.",
      "characters": ["Dorn", "Sergeant Vex", "Guard 1", "Guard 2", "Guard 3", "Guard 4"]
    },
    {
      "scene_number": 14,
      "caption": "They race up the cursed tower's collapsing stairs.",
      "visual_description": "Stone steps crumble and shift underfoot, some floating unsupported, with a bottomless void below.",
      "characters": ["Elara", "Lys", "Kaelen"]
    },
    {
      "scene_number": 15,
      "caption": "Lys disarms a magical trap at the tower's peak.",
      "visual_description": "A glowing rune circle on the floor hums with energy as Lys kneels, hands tracing counter-runes in the air.",
      "characters": ["Elara", "Lys", "Kaelen"]
    },
    {
      "scene_number": 16,
      "caption": "They emerge onto a battlement overlooking the escape bridge.",
      "visual_description": "A narrow stone bridge stretches across a deep chasm, mist swirling below, with the city's outer wall visible beyond.",
      "characters": ["Elara", "Lys", "Kaelen"]
    },
    {
      "scene_number": 17,
      "caption": "The phantom dragon returns to cut off their retreat.",
      "visual_description": "The dragon lands on the bridge ahead, wings spread, blocking the path, its ghostly form flickering.",
      "characters": ["Elara", "Lys", "Kaelen", "Phantom Dragon"]
    },
    {
      "scene_number": 18,
      "caption": "They break through and cross the bridge to freedom.",
      "visual_description": "The party sprints across the bridge as stones crack and fall behind them, reaching the far side just as the bridge collapses into the mist.",
      "characters": ["Elara", "Dorn", "Lys", "Kaelen"]
    }
  ]
}

